### Question: Static Scoping

Consider the following pseudo-code:

```c
int x = 5;

void show() {
    print(x);
}

void compute(int n) {
    int x = n + 1;
    if (n == 0) {
        show();
        return;
    }
    compute(n - 1);
}

void main() {
    int x = 99;
    compute(2);
    print(x);
}

